"""Build review tables from manually assessed sources and preserved Crossref metadata.
No network access. This generates documentation, not experimental results.
"""
import csv, html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
records={}
for filename in ('crossref_records.json','crossref_additional.json'):
    for item in json.loads((ROOT/filename).read_text()):
        if item['kind']=='doi' and 'metadata' in item:
            records[item['query'].lower()]=item
sources=[]
def paper(id,doi,level,problem,method,modalities,findings,limitations,claim,locator,**kw):
    raw=records[doi.lower()]; m=raw['metadata']
    title=html.unescape(m['title'][0])
    if m.get('subtitle'): title+=': '+m['subtitle'][0]
    s=dict(id=id,doi=doi,title=title,authors='; '.join(a.get('given','')+' '+a.get('family','') for a in m['author']),year=m['published']['date-parts'][0][0],venue=html.unescape('; '.join(m.get('container-title',[]))),volume=m.get('volume',''),issue=m.get('issue',''),pages=m.get('page',''),article=m.get('article-number',''),url='https://doi.org/'+doi,kind='Research publication',peer='Yes (journal/conference publication)',level=level,problem=problem,method=method,modalities=modalities,findings=findings,limitations=limitations,claim=claim,locator=locator,verification=raw.get('resolver',{}),metadata_url=raw['api_url'])
    s.update(kw);sources.append(s)
def doc(id,title,authors,year,venue,url,level,problem,method,claim,locator,**kw):
    s=dict(id=id,title=title,authors=authors,year=year,venue=venue,url=url,doi='',volume='',issue='',pages='',article='',kind='Standard / specification',peer='Not a peer-reviewed research paper',level=level,problem=problem,method=method,modalities='Application-dependent',findings=claim,limitations='Specification defines functionality; not evidence of AMP effectiveness.',claim=claim,locator=locator,verification={},metadata_url=url)
    s.update(kw);sources.append(s)

