fields=['ID','Paper','Year','Venue','Peer Reviewed?','Research Problem','System / Method','Modalities','Remote?','Capability Awareness?','Cross-Modal?','Bidirectional?','Presentation Tracking?','Flow Control / Pacing?','Recovery?','Human Evaluation?','Major Findings','Limitations','Relevance to AMP','DOI / Official URL','Evidence Level']
def savecsv(name,fields,rows):
    with (ROOT/name).open('w',newline='') as f:
        w=csv.writer(f);w.writerow(fields);w.writerows(rows)
savecsv('CORE_LITERATURE.csv',fields,[[s['id'],s['title'],s['year'],s['venue'],s['peer'],s['problem'],s['method'],s.get('modalities','Application-dependent'),s.get('remote','Not reported / not verified'),s.get('cap','Not reported / not verified'),s.get('cross','Not reported / not verified'),s.get('bidir','Not reported / not verified'),s.get('presentation','Not reported / not verified'),s.get('flow','Not reported / not verified'),s.get('recovery','Not reported / not verified'),s.get('human','Not reported / not applicable'),s['findings'],s['limitations'],s['claim'],s['url'],s['level']] for s in sources])
(ROOT/'SOURCE_ASSESSMENTS.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2))
refs=['# Verified references and access notes','', 'Review cutoff and access date: 15 September 2026. P = research publication, workshop paper or explicitly labeled preprint. S = standards/specifications. P18 is excluded; the numbering gap is intentional. DOI metadata verification does not imply successful publisher full-text access.','']
bib=[];audit=[]
for s in sources:
    details='; '.join(x for x in [str(s['volume'])+('('+str(s['issue'])+')' if s['issue'] else '') if s['volume'] else '', 'pp. '+s['pages'] if s['pages'] else '', 'article '+s['article'] if s['article'] else ''] if x)
    refs += [f"## {s['id']}",'',f"{s['authors']}. **{s['title']}**. *{s['venue']}*, {s['year']}"+(f', {details}' if details else '')+'. '+f"[Official record]({s['url']})."+(f" DOI: {s['doi']}." if s['doi'] else ' DOI not supplied; official URL used.'),'',f"**Type:** {s['kind']}. **Review status:** {s['peer']}. **Evidence:** {s['level']}."+(' Assessment based on abstract only.' if s['level']=='Abstract only' else ''),'',f"**Examined evidence:** {s['locator']}. **Supported use:** {s['claim']}",'',f"**Limit:** {s['limitations']}",'']
    if s.get('author_url'):refs += [f"[Author/institutional version]({s['author_url']}).",'']
    if s.get('metadata_note'):refs += ['**Metadata note:** '+s['metadata_note'],'']
    res=s['verification']; doi_status=('Crossref identity verified; resolver '+str(res.get('status','not recorded'))+' → '+res.get('url','not recorded')) if s['doi'] else 'Not supplied; official source used'
    authors_status='Verified against authoritative record'
    if s['id']=='P22':authors_status='Crossref and official AIS proceedings listing agree; deposited spelling retained'
    if s['id']=='P25':authors_status='CSIRO record used; Crossref discrepancy flagged'
    year_status='Verified'
    audit.append([s['id'],'Verified',authors_status,year_status,'Verified',doi_status,s['level'],s['claim'],s['locator'],s.get('metadata_note','')])
    typ='misc' if not s['doi'] else ('article' if 'journal' in str(records.get(s['doi'].lower(),{}).get('metadata',{}).get('type','')) else 'inproceedings')
    # Braced Unicode authors preserve institutional names and deposited author spelling.
    esc=lambda v:str(v).replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
    attrs={'title':'{'+esc(s['title'])+'}','author':' and '.join('{'+esc(a.strip())+'}' for a in s['authors'].split(';')),'year':s['year'],'url':s['url'],'note':s['kind']+'; evidence: '+s['level']}
    attrs['journal' if typ=='article' else 'booktitle' if typ=='inproceedings' else 'howpublished']=esc(s['venue'])
    for key, val in [('doi',s['doi']),('volume',s['volume']),('number',s['issue']),('pages',s['pages'])]:
        if val:attrs[key]=val
    bib.append('@'+typ+'{'+s['id']+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in attrs.items())+'\n}')
(ROOT/'REFERENCES.md').write_text('\n'.join(refs))
(ROOT/'references.bib').write_text('\n\n'.join(bib)+'\n')
savecsv('CITATION_AUDIT.csv',['Ref. ID','Title Verified','Authors Verified','Year Verified','Venue Verified','DOI Verified','Full Text?','Used for Which Claim?','Evidence locator','Uncertainty'],audit)

